42	const PAPER = new THREE.Color('#f7f4ee') // --card over --background
43	const INK = '#13293d' // --foreground
44	
45	// Shape codes shared by both point layers (see POINT_FRAG).
46	const SHAPE = { compound: 0, gene: 1, matched: 2, disease: 3, other: 4, query: 5, als: 6 } as const
47	
48	/** Layer a line or dot belongs to: always shown, real DRKG edges, or vector arithmetic. */
49	const KIND = { core: 0, edge: 1, vector: 2 } as const
50	
51	type Seg = { a: Vec3; b: Vec3; color: THREE.Color; start: number; dur: number; lane: number; base: number; kind: number; peak?: number }
52	type Dot = { pos: Vec3; color: THREE.Color; size: number; shape: number; start: number; lane: number; settle: number; kind?: number }
53	type Label = { pos: THREE.Vector3; lane: number; priority: number; node: ReactNode; opacity: (t: number, focus: number | null) => number }
54	type Cluster = { id: number; label: string; size: number; color: string }
