56	/* ---------------------------------------------------------------- helpers -- */
57	
58	function bezier(x1: number, y1: number, x2: number, y2: number) {
59	  return (x: number) => {
60	    if (x <= 0) return 0
61	    if (x >= 1) return 1
62	    let t = x
63	    for (let i = 0; i < 8; i++) {
64	      const cx = 3 * x1 * t * (1 - t) ** 2 + 3 * x2 * t * t * (1 - t) + t ** 3 - x
65	      if (Math.abs(cx) < 1e-5) break
66	      const dx = 3 * x1 * (1 - t) ** 2 + 6 * (x2 - x1) * t * (1 - t) + 3 * (1 - x2) * t * t
67	      t = Math.min(1, Math.max(0, t - cx / (dx || 1e-6)))
68	    }
69	    return 3 * y1 * t * (1 - t) ** 2 + 3 * y2 * t * t * (1 - t) + t ** 3
70	  }
71	}
72	
73	/** OKLCH → sRGB hex. Same ramp as drkg-legend's `clusterColor`, which emits CSS three can't parse. */
74	function oklch(l: number, c: number, hDeg: number) {
75	  const h = (hDeg * Math.PI) / 180
76	  const a = c * Math.cos(h)
77	  const b = c * Math.sin(h)
78	  const l_ = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3
79	  const m_ = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3
80	  const s_ = (l - 0.0894841775 * a - 1.291485548 * b) ** 3
81	  const lin = [
82	    4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_,
83	    -1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_,
84	    -0.0041960863 * l_ - 0.7034186147 * m_ + 1.707614701 * s_,
85	  ]
86	  const gamma = (x: number) => Math.round(255 * Math.min(1, Math.max(0, x <= 0.0031308 ? 12.92 * x : 1.055 * x ** (1 / 2.4) - 0.055)))
87	  return '#' + lin.map((x) => gamma(x).toString(16).padStart(2, '0')).join('')
88	}
89	const clusterHex = (id: number, color?: string) => (color?.startsWith('#') ? color : oklch(0.7, 0.085, (id * 137.508 + 200) % 360))
90	
91	const ramp = (t: number, a: number, b: number) => Math.min(1, Math.max(0, (t - a) / (b - a)))
92	/** 1 inside [a, b], easing in over `fade` before a and out after b. */
93	const window_ = (t: number, a: number, b: number, fade = 0.35) => ramp(t, a, a + fade) * (1 - ramp(t, b, b + fade))
94	const start = (lane: number) => LEAD + lane * STEP
95	
96	function useReducedMotion() {
97	  const [reduce, setReduce] = useState(() => window.matchMedia('(prefers-reduced-motion: reduce)').matches)
98	  useEffect(() => {
99	    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
100	    const on = () => setReduce(mq.matches)
101	    mq.addEventListener('change', on)
102	    return () => mq.removeEventListener('change', on)
103	  }, [])
104	  return reduce
105	}
