107	/** Clusters if the layout has them, else one group per entity type. */
108	function clustersOf(data: DrkgData): { list: Cluster[]; index: Uint8Array } {
109	  const { scene, clusters, types } = data
110	  if (clusters && scene.clusters?.length)
111	    return { list: scene.clusters.map((c) => ({ id: c.id, label: c.label, size: c.size, color: clusterHex(c.id, c.color) })), index: clusters }
112	  return { list: scene.types.map((ty, i) => ({ id: i, label: ty.name, size: ty.count, color: clusterHex(i) })), index: types }
113	}
