115	/* ---------------------------------------------------------------- shaders -- */
116	
117	const POINT_VERT = /* glsl */ `
118	  attribute vec3 color;
119	  attribute float aSize;
120	  attribute float aAlpha;
121	  attribute float aShape;
122	  attribute float aCluster;
123	  attribute float aType;
124	  uniform float uPx;
125	  uniform float uSize;
126	  uniform float uHidden[${MAX_CLUSTERS}];
127	  uniform float uHiddenType[${MAX_TYPES}];
128	  uniform vec3 uPaper;
129	  uniform float uFog;
130	  uniform vec3 uQuery;
131	  uniform float uScan;
132	  varying vec3 vColor;
133	  varying float vAlpha;
134	  varying float vShape;
135	  void main() {
136	    vec4 mv = modelViewMatrix * vec4(position, 1.0);
137	    gl_Position = projectionMatrix * mv;
138	    gl_PointSize = aSize * uSize * uPx * (24.0 / -mv.z);
139	    float fog = smoothstep(14.0, 40.0, -mv.z) * uFog;
140	    vColor = mix(color, uPaper, fog);
141	    float hidden = aCluster < 0.0 ? 0.0 : uHidden[int(aCluster + 0.5)];
142	    float hiddenType = aType < 0.0 ? 0.0 : uHiddenType[int(aType + 0.5)];
143	    float d2 = dot(position - uQuery, position - uQuery);
144	    float near = 0.12 + 0.88 * exp(-d2 / 18.0);
145	    vAlpha = aAlpha * mix(1.0, near, uScan) * mix(1.0, 0.05, hidden) * mix(1.0, 0.04, hiddenType);
146	    vShape = aShape;
147	  }
148	`
149	const POINT_FRAG = /* glsl */ `
150	  uniform vec3 uInk;
151	  varying vec3 vColor;
152	  varying float vAlpha;
153	  varying float vShape;
154	  float edge(float d, float r, float aa) { return 1.0 - smoothstep(r - aa, r, d); }
155	  void main() {
156	    vec2 c = gl_PointCoord - 0.5;
157	    float d = length(c) * 2.0;
158	    float dd = (abs(c.x) + abs(c.y)) * 2.0;
159	    float aa = max(fwidth(d), 0.02) * 1.2;
160	    vec3 col = vColor;
161	    float a;
162	    int s = int(vShape + 0.5);
163	    if (s == 0) a = edge(d, 1.0, aa);                                     // compound: filled circle
164	    else if (s == 1) a = edge(d, 1.0, aa) * (1.0 - edge(d, 0.38, aa));   // gene: ring with a clear hole
165	    else if (s == 2) { a = edge(d, 1.0, aa); col = mix(col, uInk, 1.0 - edge(d, 0.68, aa)); } // matched compound
166	    else if (s == 3) a = edge(dd, 0.95, aa);                              // disease: diamond
167	    else if (s == 4) a = (1.0 - smoothstep(0.15, 0.5, d)) * 0.8;          // other: small soft dot
168	    else if (s == 5) a = edge(d, 1.0, aa) * (1.0 - edge(d, 0.62, aa)) + edge(d, 0.24, aa); // query: target
169	    else { a = edge(dd, 1.0, aa); col = mix(col, uInk, 1.0 - edge(dd, 0.66, aa)); }         // ALS: outlined diamond
170	    a *= vAlpha;
171	    if (a <= 0.004) discard;
172	    gl_FragColor = vec4(col, a);
173	  }
174	`
175	// Every line: a thin solid stroke that draws itself on, then carries a slow pulse.
176	const LINE_VERT = /* glsl */ `
177	  attribute float aT;
178	  attribute float aStart;
179	  attribute float aDur;
180	  attribute float aWin;
181	  attribute float aBase;
182	  attribute float aLane;
183	  attribute float aSeed;
184	  attribute float aKind;
185	  attribute float aPeak;
186	  attribute vec3 color;
187	  uniform float uLane[5];
188	  uniform float uLaneTime[5];
189	  uniform float uShow[3];
190	  varying float vT; varying float vStart; varying float vDur; varying float vWin;
191	  varying float vBase; varying float vSeed; varying float vLane; varying float vTime; varying float vPeak;
192	  varying vec3 vColor;
193	  void main() {
194	    vPeak = aPeak;
195	    vT = aT; vStart = aStart; vDur = aDur; vWin = aWin; vBase = aBase; vSeed = aSeed; vColor = color;
196	    int lane = int(aLane + 0.5);
197	    vLane = uLane[lane] * uShow[int(aKind + 0.5)];
198	    vTime = uLaneTime[lane];
199	    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
200	  }
201	`
202	const LINE_FRAG = /* glsl */ `
203	  uniform float uClock;
204	  uniform float uFlow;
205	  varying float vT; varying float vStart; varying float vDur; varying float vWin;
206	  varying float vBase; varying float vSeed; varying float vLane; varying float vTime; varying float vPeak;
207	  varying vec3 vColor;
208	  void main() {
209	    if (vLane <= 0.001) discard;
210	    float r = clamp((vTime - vStart) / vDur, 0.0, 1.0);
211	    if (r <= 0.0 || vT > r) discard;
212	    float live = 1.0 - smoothstep(0.0, 0.6, vTime - vWin);
213	    float head = exp(-pow((vT - r) * 10.0, 2.0)) * (1.0 - step(1.0, r));
214	    // pulse runs on the wall clock so it keeps travelling after the timeline ends
215	    float pulse = exp(-pow((fract(uClock * 0.4 + vSeed) - vT) * 8.0, 2.0)) * uFlow;
216	    float a = mix(vBase, vPeak, live) + pulse * (0.22 + 0.3 * live) * vPeak + head * 0.35;
217	    gl_FragColor = vec4(vColor, clamp(a, 0.0, 1.0) * vLane);
218	  }
219	`
