221	/* ---------------------------------------------------------- build the run -- */
222	
223	const pill = 'rounded-md bg-card/90 px-1.5 py-0.5 text-xs leading-tight text-foreground shadow-xs ring-1 ring-border backdrop-blur-sm'
224	
225	function build(data: DrkgData) {
226	  const { scene, positions: P } = data
227	  const at = (row: number): Vec3 => [P[row * 3], P[row * 3 + 1], P[row * 3 + 2]]
228	  const profiles = [...scene.profiles].sort((a, b) => a.lane - b.lane)
229	  const end = start(profiles.length - 1) + WIN + OUTRO
230	
231	  const dots: Dot[] = [{ pos: scene.als.pos, color: new THREE.Color('#d3a2a8'), size: 13, shape: SHAPE.als, start: 0.1, lane: -1, settle: 1 }]
232	  const lines: Seg[] = []
233	  const labels: Label[] = []
234	  const focus: { target: THREE.Vector3; dist: number; query: Vec3 }[] = []
235	
236	  labels.push({
237	    pos: new THREE.Vector3(...scene.als.pos),
238	    lane: -1,
239	    priority: 0,
240	    opacity: (t) => ramp(t, 0.2, 0.6),
241	    node: (
242	      <span className={cn(pill, 'font-medium')}>
243	        ALS <span className="font-normal text-muted-foreground">{scene.als.id.replace('Disease::', '')}</span>
244	      </span>
245	    ),
246	  })
247	
248	  for (const p of profiles) {
249	    const s = start(p.lane)
250	    const win = s + WIN
251	    const hex = LANE_COLORS[p.lane % LANE_COLORS.length]
252	    const c = new THREE.Color(hex)
253	    const soft = new THREE.Color(hex).lerp(PAPER, 0.4)
254	    // Labels belong to the active profile, or to the profile hovered in the list.
255	    const live = (t: number, f: number | null) => (f !== null ? (f === p.lane ? 1 : 0) : window_(t, s, win + 0.1, 0.35))
256	
257	    p.genes.forEach((g, gi) => {
258	      if (g.alsEdge) lines.push({ a: scene.als.pos, b: g.pos, color: c, start: s + gi * 0.08, dur: 0.55, lane: p.lane, base: 0.32, kind: KIND.edge })
259	      dots.push({ pos: g.pos, color: c, size: 11, shape: SHAPE.gene, start: s + 0.3 + gi * 0.08, lane: p.lane, settle: 0.85 })
260	      const a0 = s + 1.4 + gi * 0.15
261	      lines.push({ a: g.pos, b: g.query, color: c, start: a0, dur: 0.6, lane: p.lane, base: 0.3, kind: KIND.vector })
262	      dots.push({ pos: g.query, color: c, size: 11, shape: SHAPE.query, start: a0 + 0.55, lane: p.lane, settle: 0.7, kind: KIND.vector })
263	      labels.push({
264	        pos: new THREE.Vector3(...g.pos),
265	        lane: p.lane,
266	        priority: 1,
267	        opacity: live,
268	        node: (
269	          <span className={cn(pill, 'flex items-center gap-1 font-mono font-medium')}>
270	            <span className="size-1.5 rounded-full" style={{ background: hex }} aria-hidden />
271	            {g.symbol}
272	          </span>
273	        ),
274	      })
275	    })
276	
277	    const matchRows = new Set(p.matches.map((m) => m.row))
278	    const fanned = new Set<number>()
279	    p.edges.forEach((e, j) => {
280	      const st = s + 0.45 + (p.edges.length > 1 ? j / (p.edges.length - 1) : 0) * 0.6
281	      // dozens per profile: lighter stroke so the fan reads as texture, not ink
282	      lines.push({ a: at(e.from), b: at(e.to), color: soft, start: st, dur: 0.5, lane: p.lane, base: 0.08, kind: KIND.edge, peak: 0.26 })
283	      if (!matchRows.has(e.to) && !fanned.has(e.to)) {
284	        fanned.add(e.to)
285	        dots.push({ pos: at(e.to), color: soft, size: 6, shape: SHAPE.compound, start: st + 0.5, lane: p.lane, settle: 0.5, kind: KIND.edge })
286	      }
287	    })
288	
289	    const first = p.genes[0]
290	    // first gene wins: a --from-levi scene can repeat an anchor (ALS ×3)
291	    const queries = new Map<string, Vec3>()
292	    for (const g of p.genes) if (!queries.has(g.symbol)) queries.set(g.symbol, g.query)
293	    p.matches.forEach((m, k) => {
294	      const q = queries.get(m.viaGene) ?? first?.query ?? scene.als.pos
295	      const r0 = s + 2.1 + k * 0.18
296	      lines.push({ a: q, b: m.pos, color: soft, start: r0, dur: 0.45, lane: p.lane, base: 0.18, kind: KIND.vector })
297	      const pop = r0 + 0.4
298	      dots.push({ pos: m.pos, color: c, size: k === 0 ? 12 : 9.5, shape: SHAPE.matched, start: pop, lane: p.lane, settle: k === 0 ? 1 : 0.8 })
299	      labels.push({
300	        pos: new THREE.Vector3(...m.pos),
301	        lane: p.lane,
302	        priority: 2 + k,
303	        opacity: (t, f) => {
304	          const shown = ramp(t, pop, pop + 0.3)
305	          if (f !== null) return f === p.lane ? shown : 0
306	          // After its window, only the top hit stays, at the lowest priority.
307	          return shown * Math.max(1 - ramp(t, win + 0.1, win + 0.45), k === 0 && t >= end - OUTRO ? 1 : 0)
308	        },
309	        node: (
310	          <span className={cn(pill, 'flex items-baseline gap-1.5')} title={m.name}>
311	            <span className="text-muted-foreground tabular-nums">{m.rank}</span>
312	            <span className="max-w-[10rem] truncate font-medium">{m.name}</span>
313	            <span className="font-mono text-muted-foreground tabular-nums">{m.distance.toFixed(2)}</span>
314	          </span>
315	        ),
316	      })
317	    })
318	
319	    // Camera focus: centroid of everything this profile touches.
320	    const pts = [...p.genes.flatMap((g) => [g.pos, g.query]), ...p.matches.map((m) => m.pos)].map((v) => new THREE.Vector3(...v))
321	    const target = pts.reduce((acc, v) => acc.add(v), new THREE.Vector3()).divideScalar(Math.max(1, pts.length))
322	    const radius = pts.reduce((r, v) => Math.max(r, v.distanceTo(target)), 0)
323	    const top = p.matches[0]
324	    focus.push({ target, dist: THREE.MathUtils.clamp(radius * 2.3 + 7, 13, 28), query: (top && queries.get(top.viaGene)) ?? first?.query ?? scene.als.pos })
325	  }
326	
327	  return { dots, lines, labels, focus, end, profiles }
328	}
