330	type Built = ReturnType<typeof build>
331	export type Layers = { edges: boolean; vector: boolean; labels: boolean }
332	
333	/* ------------------------------------------------------------------ world -- */
334	
335	type WorldProps = {
336	  data: DrkgData
337	  built: Built
338	  clusters: { list: Cluster[]; index: Uint8Array }
339	  hidden: Set<number>
340	  hiddenTypes: Set<number>
341	  layers: Layers
342	  status: StageStatus
343	  /** the stage was already done when this scene mounted (revisit): open on the end state */
