356	const World = memo(function World(props: WorldProps) {
357	  const { data, built, clusters, hidden, hiddenTypes, layers, status, startAtEnd, reduce, focusLane, selectedLane, replay, labelEls, labelSize, onPhase, onReveal, onHover } = props
358	  const { camera, gl, size } = useThree()
359	  const dpr = gl.getPixelRatio()
360	  const t = useRef(startAtEnd || reduce ? built.end : 0)
361	  const guided = useRef(true)
362	  const lastPhase = useRef('')
363	  const lastReveal = useRef(-1)
364	  const laneAlpha = useRef(new Float32Array(5).fill(1))
365	  // Per-lane clock: normally the global one; a selected lane replays on its own.
366	  const solo = useRef<(number | null)[]>([null, null, null, null, null])
367	
368	  useEffect(() => {
369	    if (replay === 0) return
370	    t.current = reduce ? built.end : 0
371	    solo.current = solo.current.map(() => null)
372	    guided.current = true
373	  }, [replay, reduce, built.end])
374	
375	  useEffect(() => {
376	    solo.current = solo.current.map(() => null)
377	    if (selectedLane !== null) {
378	      solo.current[selectedLane] = reduce ? built.end : start(selectedLane)
379	      guided.current = true
380	    }
381	  }, [selectedLane, reduce, built.end])
382	
383	  useEffect(() => {
384	    if (reduce) t.current = built.end
385	  }, [reduce, built.end])
386	
387	  const controls = useMemo(() => {
388	    const c = new OrbitControls(camera, gl.domElement)
389	    c.enableDamping = true
390	    c.dampingFactor = 0.08
391	    c.enablePan = false
392	    c.minDistance = 5
393	    c.maxDistance = 46
394	    c.rotateSpeed = 0.6
395	    c.addEventListener('start', () => (guided.current = false))
396	    return c
397	  }, [camera, gl])
398	  useEffect(() => () => controls.dispose(), [controls])
399	
400	  const pointMaterial = useCallback(
401	    (sizeScale: number, fog: number) =>
402	      new THREE.ShaderMaterial({
403	        vertexShader: POINT_VERT,
404	        fragmentShader: POINT_FRAG,
405	        uniforms: {
406	          uPx: { value: dpr },
407	          uSize: { value: sizeScale },
408	          uHidden: { value: new Array(MAX_CLUSTERS).fill(0) },
409	          uHiddenType: { value: new Array(MAX_TYPES).fill(0) },
410	          uPaper: { value: PAPER },
411	          uInk: { value: new THREE.Color(INK) },
412	          uFog: { value: fog },
413	          uQuery: { value: new THREE.Vector3() },
414	          uScan: { value: 0 },
415	        },
416	        transparent: true,
417	        depthWrite: false,
418	      }),
419	    [dpr],
420	  )
421	
422	  /* background cloud: one Points; colour = cluster, size = degree, shape = type */
423	  const cloud = useMemo(() => {
424	    const { positions, types, degree, scene } = data
425	    const n = positions.length / 3
426	    const palette = clusters.list.map((c) => new THREE.Color(c.color))
427	    const typeShape = scene.types.map((ty) =>
428	      ty.name === 'Compound' ? SHAPE.compound : ty.name === 'Gene' ? SHAPE.gene : ty.name === 'Disease' ? SHAPE.disease : SHAPE.other,
429	    )
430	    const p99 = Math.log1p(scene.meta.degree?.p99 ?? 1)
431	    const color = new Float32Array(n * 3)
432	    const aCluster = new Float32Array(n)
433	    const aShape = new Float32Array(n)
434	    const aSize = new Float32Array(n)
435	    for (let i = 0; i < n; i++) {
436	      const k = Math.min(clusters.index[i], MAX_CLUSTERS - 1)
437	      const c = palette[k] ?? palette[0]
438	      color[i * 3] = c.r
439	      color[i * 3 + 1] = c.g
440	      color[i * 3 + 2] = c.b
441	      aCluster[i] = k
442	      aShape[i] = typeShape[types[i]] ?? SHAPE.other
443	      // Same mapping as the legend: 4 + 8 · log1p(degree) / log1p(p99), clamped.
444	      aSize[i] = degree ? 4 + 8 * Math.min(1, Math.log1p(degree[i]) / p99) : 7
445	    }
446	    const geo = new THREE.BufferGeometry()
447	    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
448	    geo.setAttribute('color', new THREE.BufferAttribute(color, 3))
449	    geo.setAttribute('aCluster', new THREE.BufferAttribute(aCluster, 1))

import { useState, type ReactNode } from 'react'
import { ChevronDown, Eye, EyeOff } from 'lucide-react'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Separator } from '@/components/ui/separator'
import { cn } from '@/lib/utils'
import type { DrkgScene } from './drkg-data'
import { LANE_COLORS } from './lanes'

/**
 * The key to the DRKG scene: every visual channel the scene uses, drawn in the
 * scene's own style, plus Overseer-style toggles for clusters and entity types.
 * Light theme only. Collapses to a pill; the open/closed state persists.
 */

type Cluster = { id: number; label: string; size: number; dominantType: string; topTypes?: { name: string; share: number }[]; color?: string }
type Scene = Omit<DrkgScene, 'clusters' | 'meta'> & {
  meta: DrkgScene['meta'] & { degree?: { min: number; median: number; p99: number; max: number } }
  clusters?: Cluster[]
}

/** Muted, equal-lightness cluster hues; golden-angle steps keep neighbours apart. */
export function clusterColor(id: number, cluster?: { color?: string }) {
  return cluster?.color ?? `oklch(0.7 0.085 ${Math.round((id * 137.508 + 200) % 360)})`
}

const INK = 'var(--foreground)'
const NAMED = ['Compound', 'Gene', 'Disease'] as const
const STORE = 'drkg-legend-open'
const fmt = (n: number) => n.toLocaleString('en-US')

/** Entity-type glyph, the same shape the scene draws. */
export function TypeGlyph({ type, size = 12, color = INK }: { type: string; size?: number; color?: string }) {
  const r = size / 2
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} aria-hidden className="shrink-0">
      {type === 'Compound' ? (
        <circle cx={r} cy={r} r={r - 1} fill={color} />
      ) : type === 'Gene' ? (
        <circle cx={r} cy={r} r={r - 1.75} fill="none" stroke={color} strokeWidth={1.5} />
      ) : type === 'Disease' ? (
        <rect x={r - r * 0.55} y={r - r * 0.55} width={r * 1.1} height={r * 1.1} fill={color} transform={`rotate(45 ${r} ${r})`} />
      ) : (
        <circle cx={r} cy={r} r={r * 0.35} fill={color} />
      )}
    </svg>
  )
}

function Row({ glyph, channel, children }: { glyph: ReactNode; channel: string; children: ReactNode }) {
  return (
    <div className="grid grid-cols-[3rem_1fr] items-center gap-x-3 py-1">
      <div className="flex items-center gap-1">{glyph}</div>
      <p className="text-xs leading-snug">
        <span className="font-medium">{channel}</span> <span className="text-muted-foreground">· {children}</span>
      </p>
    </div>
  )
}

function Section({ title, aside, children }: { title: string; aside?: ReactNode; children: ReactNode }) {
  return (
    <section className="px-4 py-3">
      <div className="mb-1.5 flex items-baseline justify-between gap-2">
        <h3 className="text-[11px] font-medium uppercase text-muted-foreground">{title}</h3>
        {aside}
      </div>
      {children}
    </section>
  )
}

