import { DEFAULT_SRC } from '@/components/discovery/drkg-data'

/**
 * The whole-DRKG neighbourhood files written by `frontend/scripts/drkg_graph.py`
 * into `public/drkg/graph/` (format: see the script's docstring). Everything
 * here is optional: a fresh clone without them still gets the point cloud and
 * label search from the base scene files.
 */

export const GRAPH_SCRIPT = 'frontend/scripts/drkg_graph.py'
const BASE = DEFAULT_SRC.slice(0, DEFAULT_SRC.lastIndexOf('/') + 1) + 'graph/'
const MAGIC = 0x314b4744

export type Relation = { name: string; source: string; label: string; head: string; tail: string; count: number }
export type GraphIndex = {
  version: number
  entities: number
  triples: number
  shardSize: number
  shards: number
  edgeCap: number
  knnK: number
  knnScope: string
  relations: Relation[]
  types: { name: string; count: number }[]
  externalUrl: Record<string, string>
}

export type Edge = { nbr: number; rel: number; out: boolean }
export type EntityGraph = {
  edges: Edge[]
  /** full (uncapped) triple counts per relation, count desc */
  rels: { rel: number; count: number }[]
  knn: { row: number; dist: number }[]
}

/** Vite's dev server answers a missing file with index.html (200), so every loader checks the payload. */
function once<T>(load: () => Promise<T>) {
  let p: Promise<T> | null = null
  return () => {
    p ??= load().catch((e) => {
      p = null
      throw e
    })
    return p
  }
}

export const loadGraphIndex = once(async (): Promise<GraphIndex | null> => {
  const res = await fetch(BASE + 'index.json')
  if (!res.ok) return null
  const j = await res.json().catch(() => null)
  return j?.version === 1 && j.shardSize > 0 ? (j as GraphIndex) : null
})

export const loadIds = once(async (): Promise<string[] | null> => {
  const res = await fetch(BASE + 'ids.txt')
  if (!res.ok) return null
  const lines = (await res.text()).split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  return lines.length > 1000 && lines[0].includes('::') ? lines : null
})

export const loadNamesExtra = once(async (): Promise<Record<string, string>> => {
  const res = await fetch(BASE + 'names-extra.json')
  if (!res.ok) return {}
  return res.json().catch(() => ({}))
})

type Shard = { first: number; count: number; knnK: number; eo: Uint32Array; e: Uint32Array; ro: Uint32Array; r: Uint32Array; kr: Uint32Array; kd: Float32Array }
const shards = new Map<number, Promise<Shard | null>>()

function loadShard(s: number) {
  let p = shards.get(s)
  if (!p) {
    p = fetch(`${BASE}shard-${String(s).padStart(3, '0')}.bin`)
      .then((res) => (res.ok ? res.arrayBuffer() : null))
      .then((buf) => (buf ? decodeShard(buf) : null))
    p.catch(() => shards.delete(s))
    shards.set(s, p)
  }
  return p
}

export function decodeShard(buf: ArrayBuffer): Shard | null {
  if (buf.byteLength < 32) return null
  const h = new Uint32Array(buf, 0, 8)
  if (h[0] !== MAGIC) return null
  const [, first, count, nEdges, nRel, knnK] = h
  let off = 32
  const u32 = (n: number) => {
    const a = new Uint32Array(buf, off, n)
    off += n * 4
    return a
  }
  const eo = u32(count + 1)
  const e = u32(nEdges)
  const ro = u32(count + 1)
  const r = u32(nRel)
  const kr = u32(count * knnK)
  const kd = new Float32Array(buf, off, count * knnK)
  return { first, count, knnK, eo, e, ro, r, kr, kd }
}

export function readEntity(sh: Shard, row: number): EntityGraph | null {
  const i = row - sh.first
  if (i < 0 || i >= sh.count) return null
  const edges: Edge[] = []
  for (let j = sh.eo[i]; j < sh.eo[i + 1]; j++) {
    const v = sh.e[j]
    edges.push({ nbr: v & 0x1ffff, rel: (v >>> 17) & 0x7f, out: ((v >>> 24) & 1) === 1 })
  }
  const rels: EntityGraph['rels'] = []
  for (let j = sh.ro[i]; j < sh.ro[i + 1]; j++) rels.push({ rel: sh.r[j] >>> 24, count: sh.r[j] & 0xffffff })
  const knn: EntityGraph['knn'] = []
  for (let j = i * sh.knnK; j < (i + 1) * sh.knnK; j++) knn.push({ row: sh.kr[j], dist: sh.kd[j] })
  return { edges, rels, knn }
}

export async function loadEntity(row: number): Promise<EntityGraph | null> {
  const index = await loadGraphIndex().catch(() => null)
  if (!index) return null
  const sh = await loadShard(Math.floor(row / index.shardSize))
  return sh ? readEntity(sh, row) : null
}

/** Longest matching id prefix wins; `{id}` is the remainder after it. */
export function externalLink(id: string | undefined, table: Record<string, string> | undefined) {
  if (!id || !table) return null
  let best = ''
  for (const p of Object.keys(table)) if (id.startsWith(p) && p.length > best.length) best = p
  return best ? table[best].replace('{id}', encodeURIComponent(id.slice(best.length))) : null
}

/** "DRUGBANK::target::Compound:Gene" → "target", when the glossary has no label. */
export const relLabel = (r: Relation | undefined) => (r ? r.label || r.name.split('::')[1] || r.name : 'relation')

/* --------------------------------------------------------------- search -- */

export type SearchIndex = { label: string[]; lower: string[]; id: string[]; idLower: string[] }

export function buildSearch(n: number, names: Record<string, string>, extra: Record<string, string>, ids: string[] | null): SearchIndex {
  const label = new Array<string>(n)
  const lower = new Array<string>(n)
  const id = new Array<string>(n)
  const idLower = new Array<string>(n)
  for (let i = 0; i < n; i++) {
    const k = String(i)
    const full = ids?.[i] ?? ''
    // GO terms etc. without a name show their bare id ("GO:0006915"), never "Entity 123"
    const l = names[k] ?? extra[k] ?? (full ? full.slice(full.indexOf('::') + 2) : `Entity ${i}`)
    label[i] = l
    lower[i] = l.toLowerCase()
    id[i] = full
    idLower[i] = full.toLowerCase()
  }
  return { label, lower, id, idLower }
}

const wordStart = (s: string, q: string) => {
  for (let at = s.indexOf(q, 1); at > 0; at = s.indexOf(q, at + 1)) if (!/[a-z0-9]/.test(s[at - 1])) return true
  return false
}

function score(s: string, q: string) {
  if (!s) return 0
  if (s === q) return 4
  if (s.startsWith(q)) return 3
  if (!s.includes(q)) return 0
  return wordStart(s, q) ? 2 : 1
}

/** exact > prefix > word-prefix > substring over label, full id and bare id; ties by degree desc. */
export function search(ix: SearchIndex, raw: string, degree: Uint32Array | null, types: Uint8Array, typeOn: Set<number>, limit = 30) {
  const q = raw.trim().toLowerCase()
  if (!q) return []
  const hits: { row: number; s: number; d: number }[] = []
  for (let i = 0; i < ix.lower.length; i++) {
    if (typeOn.size && !typeOn.has(types[i])) continue
    const idl = ix.idLower[i]
    const s = Math.max(score(ix.lower[i], q), score(idl, q), idl ? score(idl.slice(idl.indexOf('::') + 2), q) : 0)
    if (s) hits.push({ row: i, s, d: degree?.[i] ?? 0 })
  }
  hits.sort((a, b) => b.s - a.s || b.d - a.d)
  return hits.slice(0, limit).map((h) => h.row)
}

/* --------------------------------------------------------------- styling -- */

/** Same OKLCH ramp as the stage-3 scene, keyed by type index; always paired with a glyph. */
export function oklchHex(l: number, c: number, hDeg: number) {
  const h = (hDeg * Math.PI) / 180
  const a = c * Math.cos(h)
  const b = c * Math.sin(h)
  const l_ = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3
  const m_ = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3
  const s_ = (l - 0.0894841775 * a - 1.291485548 * b) ** 3
  const lin = [
    4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_,
