  const gamma = (x: number) => Math.round(255 * Math.min(1, Math.max(0, x <= 0.0031308 ? 12.92 * x : 1.055 * x ** (1 / 2.4) - 0.055)))
  return '#' + lin.map((x) => gamma(x).toString(16).padStart(2, '0')).join('')
}
export const typeHex = (i: number) => oklchHex(0.64, 0.12, (i * 137.508 + 200) % 360)
export const clusterHex = (id: number, color?: string) => (color?.startsWith('#') ? color : oklchHex(0.7, 0.085, (id * 137.508 + 200) % 360))

